    muscles: ["legs", "glutes", "back"],
    equipment: "barbell",
    instructions: "O agachamento na caixa permite agachar até a profundidade desejada e desenvolver força explosiva. Comece em um power rack com uma caixa na altura adequada atrás de você (normalmente que leve a um agachamento paralelo). Fique sob a barra, apoiando-a na parte de trás dos ombros. Junte as escápulas e gire os cotovelos para frente, como se fosse entortar a barra sobre os ombros. Tire a barra do rack, crie um arco firme na lombar e recue para a posição. Pés mais afastados enfatizam costas, glúteos, adutores e posteriores; mais juntos, o quadríceps. Mantenha a cabeça para frente. Com costas, ombros e core firmes, empurre os joelhos e o bumbum para fora ao iniciar a descida. Jogue o quadril para trás até sentar na caixa, com as canelas perpendiculares ao chão. Pause e relaxe os flexores do quadril — nunca quique na caixa. Com o peso nos calcanhares e empurrando pés e joelhos para fora, suba conduzindo o movimento com a cabeça, mantendo a tensão dos pés à cabeça.",
